chunks.TargetContent:
for (let r = 0; r < 10; r++) {
  for (let c = 0; c < 10; c++) {
    const cellId = `${r}${c}`;
    const cellSouth = south + r * latStep;
    const cellNorth = south + (r + 1) * latStep;
    const cellWest = west + c * lngStep;
    const cellEast = west + (c + 1) * lngStep;

    const isUnmasked = UAE_UNMASKED_CELLS.includes(cellId);
    const isHighlightTarget = targetItem ? cellId === targetItem.tiers.tier1 : false;
    const isSelected = isHighlightTarget || selectedCellIdRef.current === cellId;
    const isSecondaryHighlight = cellId === "54" && !isSelected;

    const bounds: [[number, number], [number, number]] = [
      [cellSouth, cellWest],
      [cellNorth, cellEast],
    ];

    if (isUnmasked) {
      const fillColor = isSelected ? "#1B8CFE" : "transparent";
      const fillOpacity = isSelected ? 0.9 : 0;
      const strokeColor = isSelected ? "#0000FF" : isSecondaryHighlight ? "#2563EB" : "rgba(37, 99, 235, 0.4)";
      const strokeWidth = isSelected ? 2 : isSecondaryHighlight ? 1.8 : 0.8;

      const rect = L.rectangle(bounds, {
        color: strokeColor,
        weight: strokeWidth,
        fillColor,
        fillOpacity,
        className: isSelected ? "selected-grid-cell" : "enabled-grid-cell",
      });

      rect.on("click", (e) => {
        L.DomEvent.stopPropagation(e);
        selectedCellIdRef.current = cellId;
        setSelectedCellId(cellId);
        setActiveTier(2);
        setBreadcrumbs([
          { tier: 1, label: "UAE (Tier 1)", code: "UAE" },
          { tier: 2, label: `Cell ${cellId} (Tier 2)`, code: cellId },
        ]);
        renderGridRef.current?.(2, targetItem, { code: cellId });
      });

      rect.addTo(gridLayerGroupRef.current);

      const textColor = isSelected ? "#FFFFFF" : "#000000";
      const labelHtml = `
        <div style="font-family: var(--font-cairo), Cairo, sans-serif; font-size: 13px; font-weight: 700; color: ${textColor}; text-align: center; line-height: 1.2; text-shadow: ${isSelected ? "none" : "0 0 4px rgba(255,255,255,0.95), 0 0 2px #FFFFFF"}; user-select: none; pointer-events: none;">
          ${cellId}
        </div>
      `;
      const labelIcon = L.divIcon({
        className: "t1-cell-label",
        html: labelHtml,
        iconSize: [32, 26],
        iconAnchor: [16, 13],
      });
      L.marker([(cellNorth + cellSouth) / 2, (cellWest + cellEast) / 2], {
        icon: labelIcon,
        interactive: false,
      }).addTo(gridLayerGroupRef.current);
    } else if (gridTypeRef.current === "full-grid") {
      const rect = L.rectangle(bounds, {
        color: "#DEDEDE",
        weight: 0.8,
        fillColor: "url(#uaeDisabledHatchPattern)",
        fillOpacity: 1,
        className: "disabled-grid-cell",
        interactive: false,
      });
      rect.addTo(gridLayerGroupRef.current);

      // Centered dark label on masked cells matching Figma Full Grid
      const disabledLabelHtml = `
        <div style="font-family: var(--font-cairo), Cairo, sans-serif; font-size: 13px; font-weight: 700; color: #1E293B; text-align: center; line-height: 1.2; text-shadow: 0 0 3px rgba(255,255,255,0.9), 0 0 1px #FFFFFF; user-select: none; pointer-events: none;">
          ${cellId}
        </div>
      `;
      const disabledLabelIcon = L.divIcon({
        className: "t1-cell-label disabled-cell-label",
        html: disabledLabelHtml,
        iconSize: [32, 26],
        iconAnchor: [16, 13],
      });
      L.marker([(cellNorth + cellSouth) / 2, (cellWest + cellEast) / 2], {
        icon: disabledLabelIcon,
        interactive: false,
      }).addTo(gridLayerGroupRef.current);
    }
  }
}

L.polygon(UAE_BORDER_COORDINATES, {
  color: "#4B6BFB",
  weight: 2,
  dashArray: "8 6",
  fill: false,
  interactive: false,
}).addTo(gridLayerGroupRef.current);

const uaeBounds: [[number, number], [number, number]] = [
  [21.6, 50.4],
  [26.2, 57.2],
];
mapInstanceRef.current.fitBounds(uaeBounds, { padding: [16, 16], animate: false });

